const SHOP_LOCALE_MAP: Record<string, string> = {
  pt: "pt-br",
};

/**
 * Localizes a URL for one of Ledger's web properties based on the provided
 * locale. URLs on unsupported domains are returned unchanged.
 */
export function localizeUrl(url: string, locale: string): string {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return url;
  }

  switch (parsed.hostname) {
    case "www.ledger.com": {
      const localized = WWW_LOCALE_MAP[locale] ?? locale;
      parsed.pathname = `/${localized}${parsed.pathname}`;
      return parsed.toString();
    }
    case "support.ledger.com": {
      const localized = SUPPORT_LOCALE_MAP[locale] ?? locale;
      parsed.pathname = parsed.pathname.replace(/^\/hc\//, `/hc/${localized}/`);
      return parsed.toString();
    }
    case "shop.ledger.com": {
      const localized = SHOP_LOCALE_MAP[locale] ?? locale;
      parsed.pathname = `/${localized}${parsed.pathname}`;
      return parsed.toString();
    }
    default:
      return url;
  }
}

/**
 * Reads the active locale from the Redux store and returns a localized version
 * of the given URL for Ledger's web properties.
 */
export function useLocalizedUrl(url: string): string {
  const locale = useSelector(localeSelector);
  return localizeUrl(url, locale);
}

export default useLocalizedUrl;
